#!/usr/bin/env python3
"""
Correctly solve the harmonic pairs problem.
"""

import json
import math
from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_prime(n):
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.isqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def tonelli_shanks(n, p):
    """Find sqrt(n) mod p."""
    if pow(n, (p - 1) // 2, p) != 1:
        return None
    if p % 4 == 3:
        return pow(n, (p + 1) // 4, p)
    q = p - 1
    s = 0
    while q % 2 == 0:
        q //= 2
        s += 1
    if s == 1:
        return pow(n, (p + 1) // 4, p)
    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1
    c = pow(z, q, p)
    x = pow(n, (q + 1) // 2, p)
    t = pow(n, q, p)
    m = s
    while t != 1:
        i = 0
        temp = t
        while temp != 1:
            temp = pow(temp, 2, p)
            i += 1
        if i == m:
            return None
        b = pow(c, pow(2, m - i - 1, p - 1), p)
        x = (x * b) % p
        t = (t * b * b) % p
        c = (b * b) % p
        m = i
    return x

def hensel_lift(k0, p):
    """Hensel lift to get solution mod p^2."""
    m = (k0 * k0 + 1) // p
    inv_2k0 = pow(2 * k0, -1, p)
    t = (-m * inv_2k0) % p
    s = k0 + t * p
    return s

def solve_harmonic_pairs():
    """Solve the harmonic pairs problem."""
    primes_1_mod_4 = [p for p in range(5, 202) if is_prime(p) and p % 4 == 1]
    print(f"Primes ≡ 1 (mod 4) up to 201: {primes_1_mod_4}")

    # Find all k in [2, 200] where k^2 ≡ -1 (mod p^2) for some p ≡ 1 (mod 4)
    candidate_k = set()
    for p in primes_1_mod_4:
        p_squared = p * p
        k0 = tonelli_shanks(p - 1, p)
        if k0 is None:
            continue
        k0_alt = p - k0
        for root_mod_p in [k0, k0_alt]:
            s = hensel_lift(root_mod_p, p)
            for base in [s, p_squared - s]:
                k = base
                while k <= 200:
                    if 2 <= k <= 200 and (k * k + 1) % p_squared == 0:
                        candidate_k.add(k)
                    k += p_squared

    candidate_k = sorted(candidate_k)
    print(f"\nCandidate k values (satisfy k^2 ≡ -1 mod p^2): {candidate_k}")

    # Now find which k values actually produce harmonic pairs
    total_count = 0
    valid_k_with_pairs = []
    valid_primes_with_pairs = set()
    all_pairs = []

    for k in candidate_k:
        k_squared_plus_1 = k * k + 1
        count_for_k = 0
        pairs_for_k = []

        for u in range(2, 202):
            if k_squared_plus_1 % u == 0:
                v = k_squared_plus_1 // u
                if 2 <= v <= 201:
                    g = gcd(u, v)
                    if g > 1:
                        a, b = u - 1, v - 1
                        if 1 <= a <= 200 and 1 <= b <= 200:
                            if a * b + a + b == k * k:
                                count_for_k += 1
                                pairs_for_k.append((a, b, u, v, g))
                                # Find which prime divides g
                                for p in primes_1_mod_4:
                                    if g % p == 0:
                                        valid_primes_with_pairs.add(p)

        if count_for_k > 0:
            total_count += count_for_k
            valid_k_with_pairs.append(k)
            all_pairs.extend([(k, a, b, g) for a, b, u, v, g in pairs_for_k])

    valid_primes_with_pairs = sorted(valid_primes_with_pairs)

    print(f"\n=== FINAL RESULTS ===")
    print(f"correct_count: {total_count}")
    print(f"correct_valid_d_set: {valid_primes_with_pairs}")
    print(f"correct_valid_k_set: {valid_k_with_pairs}")

    print(f"\nAll harmonic pairs:")
    for k, a, b, g in all_pairs:
        print(f"  ({a}, {b}): k={k}, ab+a+b={a*b+a+b}={k}², gcd={g}")

    return total_count, valid_primes_with_pairs, valid_k_with_pairs

if __name__ == "__main__":
    count, d_set, k_set = solve_harmonic_pairs()

