    while b:
        a, b = b, a % b
    return a

# Check k values where k^2 ≡ -1 (mod 13^2 = 169)
# Need k^2 ≡ -1 ≡ 168 (mod 169)
# k^2 mod 169 for various k

# Find solutions to k^2 ≡ -1 (mod 169)
solutions_mod_169 = []
for k in range(169):
    if (k * k + 1) % 169 == 0:
        solutions_mod_169.append(k)

print(f"Solutions to k^2 ≡ -1 (mod 169): {solutions_mod_169}")

# Check which k in [2, 200] are ≡ to these solutions mod 169
candidate_k = []
for base in solutions_mod_169:
    k = base
    while k <= 200:
        if 2 <= k <= 200:
            candidate_k.append(k)
        k += 169

print(f"Candidate k values in [2, 200]: {sorted(candidate_k)}")

# Check if any of these produce valid pairs
for k in sorted(candidate_k):
    k_squared_plus_1 = k * k + 1
    pairs = []
    for u in range(2, 202):
        if k_squared_plus_1 % u == 0:
            v = k_squared_plus_1 // u
            if 2 <= v <= 201:
                g = gcd(u, v)
                if g > 1 and g % 13 == 0:  # Check if 13 divides gcd
                    a, b = u - 1, v - 1
                    if 1 <= a <= 200 and 1 <= b <= 200:
                        if a * b + a + b == k * k:
                            pairs.append((a, b, u, v, g))

    if pairs:
        print(f"k={k}: pairs = {pairs}")
    else:
        print(f"k={k}: k^2+1={k_squared_plus_1}, factorizations exist but no valid pairs with 13|gcd")

